  "proposed_rules": [
    {
      "name": "Invoices - Billing domain",
      "match_mode": "any",
      "conditions": [
        {"field": "from", "op": "contains", "value": "billing@"},
        {"field": "subject", "op": "contains", "value": "Invoice"}
      ],
      "actions": {
        "move_to": "Invoices",
        "mark_read": true
      },
      "placement": "top",
      "rationale": "Matches Invoices tagged messages from billing@ domains with 'Invoice' in subject"
    },
    {
      "name": "Invoices - Receipt subject",
      "match_mode": "any",
      "conditions": [
        {"field": "subject", "op": "contains", "value": "Receipt"}
      ],
      "actions": {
        "move_to": "Invoices",
        "mark_read": true
      },
      "placement": "top",
      "rationale": "Matches Invoices tagged messages where subject contains 'Receipt' (e.g., 'Receipt September')"
    }
  ]
}
